// Búsqueda por attributes JSONB (fuente de verdad para barras Thule).
// Flujo: marca + modelo + año + tipo de techo -> kit compatible -> barras Edge/Evo.
const raw = $input.first().json || {};
const data = (raw.query && typeof raw.query === 'object' && !Array.isArray(raw.query)) ? raw.query : raw;

const extractString = (val) => {
  if (typeof val === 'string') return val.trim();
  if (typeof val === 'object' && val !== null) {
    if (val.value) return String(val.value).trim();
    if (val.text) return String(val.text).trim();
    if (val.name) return String(val.name).trim();
  }
  return '';
};

const extractNumber = (val) => {
  if (typeof val === 'number' && Number.isFinite(val)) return val;
  if (typeof val === 'string') {
    const n = parseInt(val, 10);
    return Number.isFinite(n) ? n : null;
  }
  return null;
};

const brand = extractString(data.brand || data.make || '');
const model = extractString(data.model || '');
const year = extractNumber(data.year);
const roofRaw = extractString(data.roof_type || data.roof || data.roof_code || '').toUpperCase();

// Mapeo techo Instagram -> correlativo kit + patrón en CarroN
const ROOF_MAP = {
  ROOF_D: { kit: 5, patterns: ['Normal Roof'], mode: 'kit', label: 'Techo liso' },
  D: { kit: 5, patterns: ['Normal Roof'], mode: 'kit', label: 'Techo liso' },
  ROOF_B: { kit: 6, patterns: ['Flush Rail', 'Flush Rails'], mode: 'kit', label: 'Riel integrado/alineado' },
  B: { kit: 6, patterns: ['Flush Rail', 'Flush Rails'], mode: 'kit', label: 'Riel integrado/alineado' },
  ROOF_C: { kit: 7, patterns: ['Fixed Point', 'Fixed Points'], mode: 'kit', label: 'Punto de fijación' },
  C: { kit: 7, patterns: ['Fixed Point', 'Fixed Points'], mode: 'kit', label: 'Punto de fijación' },
  ROOF_A: { kit: null, patterns: ['Raised', 'roof railing'], mode: 'feet', label: 'Riel elevado (solo pies)' },
  A: { kit: null, patterns: ['Raised', 'roof railing'], mode: 'feet', label: 'Riel elevado (solo pies)' },
  ROOF_E: { kit: null, patterns: ['Gutter', 'gutter'], mode: 'feet', label: 'Canal de agua (solo pies)' },
  E: { kit: null, patterns: ['Gutter', 'gutter'], mode: 'feet', label: 'Canal de agua (solo pies)' },
  '5': { kit: 5, patterns: ['Normal Roof'], mode: 'kit', label: 'Kit 5 / Techo liso' },
  '6': { kit: 6, patterns: ['Flush Rail', 'Flush Rails'], mode: 'kit', label: 'Kit 6 / Riel integrado' },
  '7': { kit: 7, patterns: ['Fixed Point', 'Fixed Points'], mode: 'kit', label: 'Kit 7 / Punto de fijación' },
};

const roofKey = roofRaw.replace(/^QR:/, '');
const roofCfg = ROOF_MAP[roofKey] || ROOF_MAP[roofKey.replace('ROOF_', '')] || null;

if (!brand || !model || !year) {
  return [{ json: {
    ok: false,
    error: 'missing_slots',
    message: 'Faltan marca, modelo o año para buscar en attributes.',
    brand, model, year, roof_type: roofRaw,
  } }];
}

if (!roofCfg) {
  return [{ json: {
    ok: false,
    error: 'missing_roof_type',
    message: 'Falta tipo de techo (ROOF_A..E o kit 5/6/7).',
    brand, model, year, roof_type: roofRaw,
  } }];
}

// Patrón SQL amplio: marca + modelo en cualquier CarroN
const pattern = `%${brand}%${model}%`;
const roofPattern = roofCfg.patterns.map((p) => `%${p}%`).join('|');

return [{ json: {
  ok: true,
  brand,
  model,
  year,
  roof_type: roofRaw,
  roof_label: roofCfg.label,
  kit_correl: roofCfg.kit,
  search_mode: roofCfg.mode,
  roof_patterns: roofCfg.patterns,
  pattern,
  roof_sql_hint: roofCfg.patterns[0],
} }];

const input = $('Build Pattern').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.product_sku);

if (!input.ok) {
  return [{ json: input }];
}

const fold = (v) => String(v || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const brandF = fold(input.brand);
const modelF = fold(input.model);
const year = Number(input.year);
const roofPatterns = (input.roof_patterns || []).map((p) => fold(p));

const yearInRange = (rangeRaw) => {
  const m = String(rangeRaw || '').match(/(\d{4})\s*-\s*(\d{4}|)/);
  if (!m) return true;
  const start = parseInt(m[1], 10);
  const end = m[2] ? parseInt(m[2], 10) : 9999;
  return year >= start && year <= end;
};

const parseCaroLine = (line) => {
  const parts = String(line || '').split(',').map((p) => p.trim());
  if (parts.length < 5) return null;
  const edgePart = parts.find((p) => /Edge System:/i.test(p)) || '';
  const evoPart = parts.find((p) => /Evo System:/i.test(p)) || '';
  const edgeSkus = (edgePart.match(/\d{5,7}/g) || []).map((s) => s + (s.endsWith('TH') ? '' : 'TH'));
  const evoSkus = (evoPart.match(/\d{5,7}/g) || []).map((s) => s + (s.endsWith('TH') ? '' : 'TH'));
  return {
    brand: parts[0],
    model: parts[1],
    yearRange: parts[3],
    roofType: parts[4],
    edge_skus: [...new Set(edgeSkus)],
    evo_skus: [...new Set(evoSkus)],
  };
};

const matchesVehicle = (parsed) => {
  if (!parsed) return false;
  const b = fold(parsed.brand);
  const m = fold(parsed.model);
  if (!b.includes(brandF) && !brandF.includes(b)) return false;
  if (!m.includes(modelF) && !modelF.includes(m)) return false;
  if (!yearInRange(parsed.yearRange)) return false;
  const roofF = fold(parsed.roofType);
  return roofPatterns.some((rp) => roofF.includes(rp) || rp.includes(roofF));
};

const kits = [];
const barSkuSet = new Set();

for (const row of rows) {
  let attrs = {};
  try { attrs = JSON.parse(row.attributes_text || '{}'); } catch (_) {}
  const caroLines = Object.keys(attrs)
    .filter((k) => /^Carro\d+$/i.test(k))
    .map((k) => attrs[k])
    .filter(Boolean);

  const matchedLines = [];
  for (const line of caroLines) {
    const parsed = parseCaroLine(line);
    if (matchesVehicle(parsed)) {
      matchedLines.push(parsed);
      parsed.edge_skus.forEach((s) => barSkuSet.add(s));
      parsed.evo_skus.forEach((s) => barSkuSet.add(s));
    }
  }

  if (matchedLines.length) {
    kits.push({
      sku: row.product_sku,
      title: row.title,
      brand: row.brand,
      category: row.category,
      price: row.price_amount ? `${row.price_amount} ${row.currency || 'USD'}` : 'consultar',
      stock: row.stock_status,
      image_url: row.image_url || null,
      promo: row.promo_text || null,
      kit_correl: input.kit_correl,
      roof_label: input.roof_label,
      matched_compat: matchedLines.map((p) => `${p.brand},${p.model},${p.yearRange},${p.roofType}`),
      edge_skus: matchedLines.flatMap((p) => p.edge_skus),
      evo_skus: matchedLines.flatMap((p) => p.evo_skus),
    });
  }
}

// Para modo feet sin kit, incluir filas de pies si coinciden marca/modelo en title
if (input.search_mode === 'feet' && kits.length === 0) {
  for (const row of rows) {
    const t = fold(row.title);
    if (t.includes(brandF) && t.includes(modelF)) {
      kits.push({
        sku: row.product_sku,
        title: row.title,
        brand: row.brand,
        category: row.category,
        price: row.price_amount ? `${row.price_amount} ${row.currency || 'USD'}` : 'consultar',
        stock: row.stock_status,
        image_url: row.image_url || null,
        promo: row.promo_text || null,
        product_type: 'feet',
      });
    }
  }
}

if (!kits.length) {
  return [{ json: {
    found: false,
    count: 0,
    message: `Sin match en attributes para ${input.brand} ${input.model} ${input.year} (${input.roof_label}).`,
    query: input,
    results: [],
    bar_skus: [],
  } }];
}

return [{ json: {
  found: true,
  count: kits.length,
  source: 'attributes_jsonb',
  search_mode: input.search_mode,
  kit_correl: input.kit_correl,
  roof_label: input.roof_label,
  query: input,
  results: kits.slice(0, 5),
  bar_skus: [...barSkuSet].slice(0, 12),
  note: input.search_mode === 'feet'
    ? 'Techo elevado/canal: recomendar pies Thule compatibles; no aplica kit 5/6/7.'
    : 'Kits y SKUs Edge/Evo extraídos de CarroN en attributes. Usar bar_skus para detalle de barras.',
} }];

const base = $('Format Response').first().json;
if (!base.found) return [{ json: base }];

const barRows = $input.all().map((i) => i.json).filter((r) => r && r.product_sku);
const bars = barRows.map((r) => ({
  sku: r.product_sku,
  title: r.title,
  brand: r.brand,
  category: r.category,
  price: r.price_amount ? `${r.price_amount} ${r.currency || 'USD'}` : 'consultar',
  stock: r.stock_status,
  image_url: r.image_url || null,
  promo: r.promo_text || null,
  product_type: /evo/i.test(r.title) ? 'evo_bar' : (/edge/i.test(r.title) ? 'edge_bar' : 'bar'),
}));

return [{ json: {
  ...base,
  bars,
  bars_count: bars.length,
} }];
